  ((select id from catalog.skus where slug = 'super-special-20w50'), 'cta', 1, 'فريق المبيعات يخدم محلات البناشر ومراكز الخدمة والأساطيل في المنطقة الغربية.', 'Our sales team serves tire shops, service centres and fleets across the Western Region.'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'overview', 0, 'زيت محرك صناعي نقي 100% (Virgin Synthetic) بدرجة SAE 5W-30 ومعيار API SN، طُوّر بأحدث تقنيات الزيوت التخليقية مع إضافات معتمدة عالمياً ليقدم حماية فائقة وأداءً متفوقاً لجميع سيارات البنزين الحديثة.', 'A 100% virgin synthetic engine oil in SAE 5W-30 meeting the API SN standard, developed with the latest synthetic-oil technology and globally certified additives to deliver superior protection and performance for all modern petrol vehicles.'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'overview', 1, 'لزوجته المنخفضة عند التشغيل البارد تُسرّع وصول الزيت إلى أجزاء المحرك وتخفض استهلاك الوقود، فيما يحافظ على ثباته الكامل في درجات الحرارة العالية المميزة لمناخنا الصحراوي. يوصى بتغييره كل 10,000 كم.', 'Its low cold-start viscosity speeds oil flow to engine components and reduces fuel consumption, while remaining fully stable at the high temperatures typical of our desert climate. An oil change every 10,000 km is recommended.'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'benefits', 0, 'مقاومة عالية للحرارة', 'High heat resistance'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'benefits', 1, 'إطالة عمر المحرك', 'Extended engine life'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'benefits', 2, 'خصائص ممتازة لمقاومة التآكل', 'Excellent anti-wear properties'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'benefits', 3, 'منع الرواسب والشوائب', 'Deposit and impurity prevention'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'benefits', 4, 'توفير في استهلاك الوقود', 'Fuel-consumption savings'),
