  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'quality', 1, 'مصنعة وفق مواصفات أرامكو السعودية وSASO', 'Manufactured to Saudi Aramco and SASO specifications'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'quality', 2, 'زيوت أساس بكر 100% من المجموعتين الثانية والثالثة (Group II & III)', '100% virgin Group II & III base oils'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'quality', 3, 'ضمان رضا 100% — SAUDI MADE', '100% satisfaction guarantee — SAUDI MADE'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'manufacturer', 0, 'الشركة المصنعة: بترو سبيشل لزيوت التشحيم — السجل التجاري 4030399323', 'Manufacturer: Petro Special Lubricants — Commercial Registration 4030399323'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'manufacturer', 1, 'طريق مكة القديم، كيلو 8، جدة 22347، المملكة العربية السعودية', 'Old Makkah Road, Km 8, Jeddah 22347, Saudi Arabia'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'manufacturer', 2, 'منتج وطني سعودي — SAUDI MADE، ضمن مسيرة رؤية 2030', 'A Saudi national product — proudly SAUDI MADE, aligned with Vision 2030'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'hse', 0, 'الاستخدام الآمن: تجنب ملامسة الزيت المستعمل للجلد لفترات طويلة. اغسل الجلد جيدًا بالماء والصابون بعد الاستخدام.', 'Safe use: Avoid prolonged skin contact with used oil. Wash skin thoroughly with soap and water after use.'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'hse', 1, 'تحذيرات العبوة: لا تستخدم العبوات الفارغة لتخزين الوقود أو المذيبات، حيث قد تسبب البقايا خطر اشتعال.', 'Container warnings: Do not use empty containers to store fuel or solvents; residues can create a fire hazard.'),
  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'hse', 2, 'المسؤولية البيئية: حافظ على البيئة من التلوث عبر التخلص من الزيوت والعبوات في مراكز إعادة التدوير أو التخلص المعتمدة. لا تقم بسكب الزيت في المصارف أو التربة أو المياه.', 'Environmental responsibility: Protect the environment by disposing of oils and containers at approved recycling or disposal centres. Never pour oil into drains, soil or water.'),
