  ((select id from catalog.skus where slug = 'synthetic-special-5w30'), 'cta', 1, 'فريق المبيعات يخدم محلات البناشر ومراكز الخدمة والأساطيل في المنطقة الغربية.', 'Our sales team serves tire shops, service centres and fleets across the Western Region.'),
  ((select id from catalog.skus where slug = 'super-special-diesel-10w40'), 'overview', 0, 'زيت محركات ديزل سوبر سبيشل ديزل 10W-40 بدرجة SAE 10W-40 ومعيار API CI-4، مُصنّع من زيت أساس بكر 100% مع حزمة إضافات قوية للمحركات العاملة تحت الأحمال الثقيلة — الشاحنات والحافلات والمعدات والمركبات التجارية.', 'Super Special Diesel 10W-40 is a SAE 10W-40 diesel engine oil meeting API CI-4, blended from 100% virgin base oil with a robust additive package for engines working under heavy loads — trucks, buses, equipment and commercial vehicles.'),
  ((select id from catalog.skus where slug = 'super-special-diesel-10w40'), 'overview', 1, 'يتميز بقدرة عالية على تشتيت السخام ومنع تراكم الرواسب، مع ثبات لزوجة استثنائي في درجات الحرارة العالية وحماية موثوقة للشواحن التوربينية. يوصى بتغيير الزيت كل 5,000 كم حسب ظروف التشغيل.', 'It excels at dispersing soot and preventing deposit build-up, with exceptional viscosity stability at high temperatures and dependable protection for turbochargers. An oil change every 5,000 km is recommended, depending on operating conditions.'),
  ((select id from catalog.skus where slug = 'super-special-diesel-10w40'), 'benefits', 0, 'حماية فائقة تحت الأحمال الثقيلة', 'Superior protection under heavy loads'),
  ((select id from catalog.skus where slug = 'super-special-diesel-10w40'), 'benefits', 1, 'تشتيت السخام ومنع الرواسب', 'Soot dispersal and deposit prevention'),
  ((select id from catalog.skus where slug = 'super-special-diesel-10w40'), 'benefits', 2, 'ثبات اللزوجة في الحرارة العالية', 'Viscosity stability at high heat'),
