  ((select id from catalog.skus where slug = 'raval-20w50'), 'benefits', 1, 'إطالة عمر المحرك إلى أقصى حد', 'Engine life extended to the maximum'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'benefits', 2, 'حماية ممتازة ضد التآكل والصدأ', 'Excellent wear and rust protection'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'benefits', 3, 'مقاومة الأكسدة', 'Oxidation resistance'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'benefits', 4, 'منع تكوّن الرواسب', 'Deposit prevention'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'benefits', 5, 'مقاومة تكوّن الرغوة', 'Foam-formation resistance'),
