  ((select id from catalog.skus where slug = 'raval-20w50'), 'quality', 1, 'مصنعة وفق مواصفات أرامكو السعودية وSASO', 'Manufactured to Saudi Aramco and SASO specifications'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'quality', 2, 'زيوت أساس بكر 100% من المجموعتين الثانية والثالثة (Group II & III)', '100% virgin Group II & III base oils'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'quality', 3, 'ضمان رضا 100% — SAUDI MADE', '100% satisfaction guarantee — SAUDI MADE'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'manufacturer', 0, 'الشركة المصنعة: بترو سبيشل لزيوت التشحيم — السجل التجاري 4030399323', 'Manufacturer: Petro Special Lubricants — Commercial Registration 4030399323'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'manufacturer', 1, 'طريق مكة القديم، كيلو 8، جدة 22347، المملكة العربية السعودية', 'Old Makkah Road, Km 8, Jeddah 22347, Saudi Arabia'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'manufacturer', 2, 'منتج وطني سعودي — SAUDI MADE، ضمن مسيرة رؤية 2030', 'A Saudi national product — proudly SAUDI MADE, aligned with Vision 2030'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'hse', 0, 'الاستخدام الآمن: تجنب ملامسة الزيت المستعمل للجلد لفترات طويلة. اغسل الجلد جيدًا بالماء والصابون بعد الاستخدام.', 'Safe use: Avoid prolonged skin contact with used oil. Wash skin thoroughly with soap and water after use.'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'hse', 1, 'تحذيرات العبوة: لا تستخدم العبوات الفارغة لتخزين الوقود أو المذيبات، حيث قد تسبب البقايا خطر اشتعال.', 'Container warnings: Do not use empty containers to store fuel or solvents; residues can create a fire hazard.'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'hse', 2, 'المسؤولية البيئية: حافظ على البيئة من التلوث عبر التخلص من الزيوت والعبوات في مراكز إعادة التدوير أو التخلص المعتمدة. لا تقم بسكب الزيت في المصارف أو التربة أو المياه.', 'Environmental responsibility: Protect the environment by disposing of oils and containers at approved recycling or disposal centres. Never pour oil into drains, soil or water.'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'cta', 0, 'اسأل عن التوفر والتوريد بالجملة', 'Ask about availability and wholesale supply'),
  ((select id from catalog.skus where slug = 'raval-20w50'), 'cta', 1, 'فريق المبيعات يخدم محلات البناشر ومراكز الخدمة والأساطيل في المنطقة الغربية.', 'Our sales team serves tire shops, service centres and fleets across the Western Region.'),
  ((select id from catalog.skus where slug = 'raval-5w30'), 'overview', 0, 'زيت محرك رافال 5W-30 بدرجة لزوجة SAE 5W-30 ومعيار أداء API SN، مُصنّع من زيت أساس بكر 100% مصدره أرامكو السعودية، وممزوج وفق مواصفات أمريكية صارمة مع إضافات معتمدة من كبرى الشركات العالمية. مناسب لجميع سيارات البنزين، ويمنح المحرك حماية متكاملة من التآكل والرواسب في ظروف القيادة اليومية.', 'Raval 5W-30 is a SAE 5W-30 engine oil meeting the API SN performance standard, blended from 100% virgin base oil sourced from Saudi Aramco to strict American specifications with additives certified by the world''s leading companies. Suitable for all petrol vehicles, it gives the engine complete protection against wear and deposits in everyday driving.'),
  ((select id from catalog.skus where slug = 'raval-5w30'), 'overview', 1, 'صُمم خصيصاً لمواجهة الظروف القاسية للمناخ الصحراوي ودرجات الحرارة التشغيلية العالية، بثبات استثنائي في اللزوجة ومقاومة عالية للتحلل الحراري. يوصى بتغيير الزيت كل 10,000 كم للحفاظ على أفضل أداء.', 'It is purpose-built for the harsh desert climate and high operating temperatures, with exceptional viscosity stability and strong resistance to thermal breakdown. An oil change every 10,000 km is recommended for peak performance.'),
